PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (user_id TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS plans (version TEXT PRIMARY KEY, question_ids TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spaces (id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('waiting','active','dissolved')), start_day TEXT, plan_version TEXT NOT NULL REFERENCES plans(version), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (space_id TEXT NOT NULL REFERENCES spaces(id), user_id TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(space_id,user_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_space ON members(user_id) WHERE active=1;
CREATE TRIGGER IF NOT EXISTS max_two_members BEFORE INSERT ON members WHEN (SELECT count(*) FROM members WHERE space_id=NEW.space_id)>=2 BEGIN SELECT RAISE(ABORT,'space_full'); END;
CREATE TABLE IF NOT EXISTS invites (token_hash TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), expires_at INTEGER NOT NULL, used_by TEXT);
CREATE TABLE IF NOT EXISTS rounds (id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), question_id TEXT NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('daily','free')), creator TEXT NOT NULL, accepted_by TEXT, closed INTEGER NOT NULL DEFAULT 0 CHECK(closed IN (0,1)), created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_daily_round ON rounds(space_id,day) WHERE kind='daily';
CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT NOT NULL, round_id TEXT REFERENCES rounds(id), text TEXT NOT NULL, note TEXT NOT NULL, revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','submitted')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_round_entry ON entries(owner,round_id) WHERE round_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS entry_revisions (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, revision INTEGER NOT NULL, text TEXT NOT NULL, note TEXT NOT NULL, saved_at TEXT NOT NULL, PRIMARY KEY(entry_id,revision));
CREATE TABLE IF NOT EXISTS submissions (round_id TEXT NOT NULL REFERENCES rounds(id), owner TEXT NOT NULL, entry_id TEXT REFERENCES entries(id) ON DELETE SET NULL, body TEXT, entry_revision INTEGER NOT NULL, submitted_at TEXT NOT NULL, withdrawn_at TEXT, operation_id TEXT NOT NULL, PRIMARY KEY(round_id,owner), UNIQUE(owner,operation_id), CHECK(body IS NOT NULL OR withdrawn_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES rounds(id), owner TEXT NOT NULL, text TEXT NOT NULL, reply_to TEXT REFERENCES comments(id) ON DELETE SET NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL, UNIQUE(owner,operation_id));
CREATE TABLE IF NOT EXISTS skips (owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT NOT NULL, PRIMARY KEY(owner,question_id));
PRAGMA user_version=1;
